from itertools import combinations

A = {0,1,2}
B = {3,4,5,6}
edges = [(u,v) for u in A for v in B]
edges = [tuple(sorted(e)) for e in edges]
print(edges)

# Check no triangle
adj = {i:set() for i in range(7)}
for u,v in edges:
    adj[u].add(v); adj[v].add(u)

for a,b,c in combinations(range(7),3):
    if b in adj[a] and c in adj[a] and c in adj[b]:
        print("TRIANGLE", a,b,c)

# Check maximal: every non-edge, adding creates triangle
for u,v in combinations(range(7),2):
    if v not in adj[u]:
        if not (adj[u] & adj[v]):
            print("NOT MAXIMAL:", u,v)

print("Fixed edges present:", (0,6) in edges, (1,5) in edges)
